@@ -13,3 +13,13 @@ export async function addItem(item) {
   const id = Math.max(0, ...items.map((i) => i.id)) + 1;
   return saveItem({ tags: [], unit: "", ...item, id });
 }
+
+/** Takes `n` from an item's qty and returns the updated item. */
+export async function useItem(id, n = 1) {
+  if (!Number.isInteger(n) || n < 0) throw new Error("Amount must be a whole number, 0 or more.");
+  const items = await fetchItems();
+  const item = items.find((i) => i.id === id);
+  if (!item) throw new Error(`No item with id ${id}.`);
+  if (n > item.qty) throw new Error(`Only ${item.qty} left of ${item.name}.`);
+  return saveItem({ ...item, qty: item.qty - n });
+}
